export const useSetGetTripDashboardQueryData = () => {
  const queryClient = useQueryClient();
  return (tripId: number,updater: Awaited<ReturnType<typeof getTripDashboard>> | undefined | ((old: Awaited<ReturnType<typeof getTripDashboard>> | undefined) => Awaited<ReturnType<typeof getTripDashboard>> | undefined)) => {
    queryClient.setQueryData(getGetTripDashboardQueryKey(tripId), updater);
  };
}

/**
 * @summary Get trip dashboard
 */
export const useGetGetTripDashboardQueryData = () => {
  const queryClient = useQueryClient();
  return (tripId: number,) =>
    queryClient.getQueryData<Awaited<ReturnType<typeof getTripDashboard>>>(getGetTripDashboardQueryKey(tripId));
}


